-- V14.4 — canonical exercise catalog + progression graph

create table if not exists public.exercise_catalog (
  id text primary key, name text not null, category text not null, skill text not null, pattern text not null,
  kind text not null, difficulty smallint not null check (difficulty between 1 and 5),
  equipment text[] not null default '{}', side_mode text not null default 'bilateral',
  rep_min integer, rep_max integer, hold_min integer, hold_max integer, rest_sec integer,
  default_target text, detail text, cue text, active boolean not null default true, sort_order integer not null default 100,
  metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table if not exists public.exercise_progressions (
  from_exercise_id text not null references public.exercise_catalog(id) on delete cascade,
  to_exercise_id text not null references public.exercise_catalog(id) on delete cascade,
  relation_type text not null default 'progression',
  promotion_rule jsonb not null default '{}'::jsonb,
  sort_order integer not null default 0, primary key (from_exercise_id,to_exercise_id), check (from_exercise_id <> to_exercise_id)
);

alter table public.exercise_catalog enable row level security;
alter table public.exercise_progressions enable row level security;
drop policy if exists "active exercise catalog readable" on public.exercise_catalog;
create policy "active exercise catalog readable" on public.exercise_catalog for select to authenticated using (active = true);
drop policy if exists "active exercise progressions readable" on public.exercise_progressions;
create policy "active exercise progressions readable" on public.exercise_progressions for select to authenticated using (exists (select 1 from public.exercise_catalog e where e.id=from_exercise_id and e.active));
revoke all on public.exercise_catalog from anon, public; grant select on public.exercise_catalog to authenticated;
revoke all on public.exercise_progressions from anon, public; grant select on public.exercise_progressions to authenticated;

on conflict (id) do update set name=excluded.name,category=excluded.category,skill=excluded.skill,pattern=excluded.pattern,kind=excluded.kind,difficulty=excluded.difficulty,equipment=excluded.equipment,side_mode=excluded.side_mode,rep_min=excluded.rep_min,rep_max=excluded.rep_max,hold_min=excluded.hold_min,hold_max=excluded.hold_max,rest_sec=excluded.rest_sec,default_target=excluded.default_target,detail=excluded.detail,cue=excluded.cue,sort_order=excluded.sort_order,updated_at=now();


create index if not exists exercise_catalog_skill_idx on public.exercise_catalog(skill,active,difficulty);
create index if not exists exercise_catalog_category_idx on public.exercise_catalog(category,active);
create index if not exists exercise_progressions_from_idx on public.exercise_progressions(from_exercise_id,sort_order);
create index if not exists exercise_progressions_to_idx on public.exercise_progressions(to_exercise_id);

comment on table public.exercise_catalog is 'Canonical coach-approved exercise library. Program blocks reference these stable IDs.';
comment on table public.exercise_progressions is 'Directed progression graph used by Edit Plan and progression decisions.';
